#!/bin/sh
# Exercise the actual S05crond text generated by register_cron_initd().
set -u

root=${ROOT:-.}
work=$(mktemp -d) || exit 1
trap 'rm -rf "$work"' EXIT INT TERM
mkdir -p "$work/bin" || exit 1

cat > "$work/bin/crond" <<'MOCK'
#!/bin/sh
exit "${CROND_RC:-0}"
MOCK
cat > "$work/bin/pidof" <<'MOCK'
#!/bin/sh
[ "${PIDOF_RC:-1}" -eq 0 ] || exit 1
echo 123
MOCK
cat > "$work/bin/killall" <<'MOCK'
#!/bin/sh
exit "${KILLALL_RC:-0}"
MOCK
cat > "$work/bin/sleep" <<'MOCK'
#!/bin/sh
exit 0
MOCK
chmod +x "$work/bin/crond" "$work/bin/pidof" "$work/bin/killall" "$work/bin/sleep" || exit 1

initd_cron="$work/S05crond"
script_version=''
opkg() { return 1; }
. "$root/scripts/_xkeen/02_install/07_install_register/03_register_cron.sh"
register_cron_initd || exit 1
sed "s|cron_initd=\"/opt/sbin/crond\"|cron_initd=\"$work/bin/crond\"|" \
    "$initd_cron" > "$work/S05crond.test" || exit 1
mv "$work/S05crond.test" "$initd_cron" || exit 1
chmod +x "$initd_cron" || exit 1

PATH="$work/bin:$PATH"
export PATH
pass=0
fail=0
check() {
    if [ "$2" = "$3" ]; then
        printf 'OK   %s\n' "$1"
        pass=$((pass + 1))
    else
        printf 'FAIL %s: expected [%s], got [%s]\n' "$1" "$3" "$2"
        fail=$((fail + 1))
    fi
}
run_service() {
    _service_command="$1"
    "$initd_cron" "$_service_command" > "$work/output" 2>&1
    result_code=$?
}

CROND_RC=17
PIDOF_RC=1
KILLALL_RC=0
export CROND_RC PIDOF_RC KILLALL_RC
run_service start
check 'failed crond start returns failure' "$result_code" 1
if grep -q 'не удалось запустить' "$work/output"; then start_error=yes; else start_error=no; fi
check 'failed crond start reports error' "$start_error" yes

PIDOF_RC=1
CROND_RC=17
KILLALL_RC=0
export PIDOF_RC CROND_RC KILLALL_RC
run_service restart
check 'restart propagates failed start' "$result_code" 1
if grep -q 'не удалось перезапустить' "$work/output"; then restart_error=yes; else restart_error=no; fi
check 'failed restart reports error' "$restart_error" yes

PIDOF_RC=1
export PIDOF_RC
run_service stop
check 'stop is successful when cron is already stopped' "$result_code" 0
if grep -q 'не запущен' "$work/output"; then stop_stopped=yes; else stop_stopped=no; fi
check 'stop reports already-stopped state' "$stop_stopped" yes

run_service status
check 'status command completes when cron is stopped' "$result_code" 0
if grep -q 'не запущен' "$work/output"; then status_stopped=yes; else status_stopped=no; fi
check 'status reports stopped state' "$status_stopped" yes

printf '\n=== passed: %s, failed: %s ===\n' "$pass" "$fail"
[ "$fail" -eq 0 ]
